   "module": "changshi",
   "q": "习近平总书记在庆祝中国共产党成立100 周年大会上的讲话指出，坚持党指挥枪、建设自己的人民军队，是党在血与火的斗争中得出的颠扑不破的真理。下列关于党对军队绝对领导的根本原则和制度的表述正确的有几项（ ）①南昌起义，标志着党独立领导革命战争、创建人民军队和武装夺取政权的开端②三湾改编，从组织上确立了党对军队的领导③古田会议，确立了马克思主义建党建军原则，确立了军队政治工作的方针、原则、制度④党的十八大，把坚持党对人民军队绝对领导上升为新时代坚持和发展中国特色社会主义的基本方略⑤党的十九大，把“中央军事委员会实行主席负责制”写入党章",
