   "explain": "】本题考查地理常识。 A 项，2020 年珠峰高程测量，测量队员便是从珠峰地区的日喀则一等水准点起测，将 高程传递至珠峰脚下的6 个交会点；是测量珠峰山脚的海拔高度，理论上可以从 青岛的水准零点出发，每隔24 米竖立一个标尺，把水准仪放在中间位置，读出两 个标尺的高度差。这样一站一站地测量出高度，一直测到珠峰脚下，然后把之前 的高度差累加起来得出准确数字，就是珠峰山脚零点与黄海平均海平面的高度差。 在过去几十年中，中国的测绘工作者在全国建立了两万多个相对青岛水准原点的 精确的固定水准点，这次测量，就是从日喀则的国家深层基岩水准点开始复测。 为了保证测量的精确。复测要经过拉孜县、定日县和聂拉木县，构建最新的一等 水准网，然后以一等水准网为基准，对珠峰地区进行二等水准测量，一直推进到 珠峰大本营的水准基点。在从这里，使用三等水准测量，推进到珠峰脚下6 个峰 全国服务电话：400-6",
