   "explain": "】本题考查人文常识。 全国服务电话：400-6353-606 A 项，白瓷最早出现于东汉时期，但成熟的白瓷要到隋代才出现，唐代达到极盛时期， 北方地区生产白瓷的窑址有河北内邱、临城邢窑、曲阳窑，河南巩县窑、鹤壁窑， 密县窑、登封窑、郏县窑、荥阳窑、安阳窑；山西浑源窑、平定窑，陕西耀州窑， 安徽萧窑等。其中以邢窑白瓷为代表，与南方地区越窑青瓷相匹敌，世称“南青 北白”。故“唐朝富商李某在女儿出嫁时陪送白瓷数十套”的情形在历史上有可 能发生； B 项，公元前60 年，为了管理统一后的西域，西汉在乌垒城(今轮台县境内)建立西域 都护府，正式在西域设官、驻军、推行政令，开始行使国家主权。故“秦朝时郑某 升任西域都护，友人为他摆酒饯行”的情形在历史上不可能发生； C 项，唐高宗显庆六年，创设市舶使于广州，总管海路邦交外贸，派专官充任。市舶使 的职责主要是向前来贸易的船舶征收关税，代表宫廷",
