   "q": "下列与急救有关的说法正确的是（ ）",
   "options": [
    "误食强酸可以立即口服氢氧化铝凝胶",
    "误服氨水者应该立即进行洗胃或催吐",
    "农药沾染皮肤中毒可立即用热水擦洗",
    "烧伤时应立即饮用大量凉水补充体液"
   ],
   "answer": 0,
   "explain": "】本题考查生活常识。 A 项，如果是误服的是强酸，我们可以口服3%—4%的氢氧化铝凝胶或者是氢氧化钙， 这样可以中和酸性；如果是误服的是强碱，我们可以立即口服稀释的米醋、2%的 醋酸或者柠檬汁，这样可以中和碱性的药物； B 项，误服氨水者，此时切不可催吐，也不能洗胃，以免发生食道和胃穿孔。可服生鸡 蛋清50 毫升、牛奶200 毫升或植物油50—100 毫升等润滑缓和剂以减轻刺激； C 项，农药沾染皮肤的，应脱去被农药污染的衣服，用清水及肥皂（不要用热水）充分 洗涤被污染的部位。洗涤后用洁净的布或毛巾擦干； D 项，烧伤时应立即用大量凉水冲洗。轻度烧伤尤其是不严重的肢体烧伤，应立即用 清水冲洗或将患肢浸泡在冷水中10—20 分钟，如不方便浸泡，可用湿毛巾或布单 盖在患部，然后浇冷水、以使伤口尽快冷却降温，减少损伤；烧伤的患者不能立 即饮用大量凉水，大量的饮水会发生水中毒，可以让患者喝一些含盐",
