   "answer": 2,
   "explain": "】逻辑填空题。第一空，根据空前“急救专家探索出新路径”，故空内应体现腹部 提压心肺复苏技术出现之意。 A 项，“异军突起”比喻一支新力量突然出现，符合文意，保留； B 项，“横空出世”形容横在空中，浮出人世，或比喻卓尔不群，不符合文意，排除； C 项，“应运而生”泛指随着某种形势而产生，符合文意，保留； D 项，“粉墨登场”多比喻坏人经过一番乔装打扮爬上政治舞台，不符合文意，排除。 第二空，根据空后解释，该技术与传统心肺复苏技术相比，是利用腹部提压心肺复苏 仪达到起腹心动、起腹呼吸的目的，故该空应体现该技术做法与其它技术不同之意。 A 项，“推陈出新”指去掉旧事物的糟粕，取其精华，多指继承文化遗产，且文段未提 及“去掉旧的”，不符合文意，排除； C 项，“另辟蹊径”指另外开辟一条道路，符合文意，当选。 故正确答案为C。 全国服务电话：400-6353-606",
