   "module": "yanyu",
   "q": "基层是国家治理体系的末梢，但这末梢并非______的边角毫末，而是治理现代化总体方略的关键词，也是人民群众日常生活获得感的中转站，基层治理要满足群众的殷切期望，因此，需要______重心下移的治理体系，增添治理资源、激发治理活力，如此基层才能“发声呐喊”。全国服务电话：400-6353-606依次填入画横线部分最恰当的一项是（ ）",
