   "explain": "】逻辑填空题。第一空，“并非……而是……”构成反向并列，前后含义相反。“而 是”之后“关键词”强调重要，必不可少，故该空应与其内容相反，要体现出不重要 的意思。 A 项，“无足轻重”意思是无关紧要，有它没它都行，能够体现出不重要的意思，符合 文意，保留； B 项，“可有可无”意思是有它没它都行，能够体现出不重要的意思，符合文意，保 留； C 项，“默默无闻”形容没有名声，不为人们所知道，不代表不重要，不符合文意，排 除； 全国服务电话：400-6353-606 D 项，“微乎其微”形容非常少或非常小，和重不重要无关，不符合文意，排除。 第二空，搭配“治理体系”。 A 项，“构建治理体系”为常用搭配，当选； B 项，“规范”常与“体制”搭配，和“治理体系”搭配不当，排除。 故正确答案为A。",
