   "module": "yanyu",
   "q": "新闻工作一方面不能抱残守缺，不思改革，对于各种呼声______；另一方面又不能______，不加辨别地跟着各种思潮跑，没有一个界限。不然，就会乱套。对当前的各种社会思潮，我们要冷静地通过自己的头脑去思考，不能受随意性的支配。依次填入画横线部分最恰当的一项是（ ）",
   "options": [
    "敷衍了事 随波逐流",
    "不以为意 拾人牙慧",
    "莫衷一是 避重就轻",
    "置若罔闻 人云亦云"
   ],
   "answer": 3,
   "explain": "】逻辑填空题。第一空，根据空前提示“不能抱残守缺，不思改革”，故空处应体现 出“不听各种呼声”的含义。 A 项，“敷衍了事”指做事马虎，不认真，表面上应付，不符合文意，排除； B 项，“不以为意”指不在意，不把它放在心上，表示轻视，符合文意，保留； C 项，“莫衷一是”指不能判定哪个对，哪个错，不符合文意，排除； D 项，“置若罔闻”形容听见了不加理睬，符合文意，保留。 第二空，根据空后解释“不加辨别地跟着各种思潮跑”可知，空处应体现出“完全听 从别人的意见”。 B 项，“拾人牙慧”比喻抄袭、套用别人的语言和文字，当作自己的话，不符合文意， 排除； D 项，“人云亦云”指别人说什么，自己也跟着说什么，形容没有主见，随声附和，符 合文意，当选。 故正确答案为D。",
