   "module": "shuliang",
   "q": "企业列出500 万元设备采购预算，如用于购买x台进口设备，最后剩余20 万元。经董事会研究后，决定购买质量更高的同类国产设备，单价仅为进口设备的75%。当前预算可购买x + 3台，最后剩余5 万元。问国产设备的单价在以下哪个范围内（ ）",
