   "module": "shuliang",
   "q": "某县通过发展旅游业来实现乡村振兴，引进了甲、乙、丙、丁、戊和己6 名专家。其中甲、乙、丙是环境保护专家，丁、戊、己是旅游行业专家，甲、丁、戊熟悉社交媒体宣传。现要将6 名专家平均分成2 个小组，每个小组都要有环境保护专家、旅游行业专家和熟悉社交媒体宣传的人，问有多少种不同的分组方式（ ）",
