   "q": "某水果种植特色镇创办水果加工厂，从去年年初开始通过电商平台销售桃汁、橙汁两种产品。从去年2 月开始，每个月桃汁的销量都比上个月多5000 盒，橙汁的销量都比上个月多2000 盒。已知去年第一季度桃汁的总销量比橙汁少4.5 万盒，则去年桃汁的销量比橙汁（ ）",
