   "explain": "】定义判断。选非题。关键词：归因不变性原则：某种特定原因；在许多情境下总 是与某种结果相伴；人们就会把特定结果归结于那一原因。归因折扣原则：不完全相 信某一现象的形成由于某种原因导致；如果存在其他似是而非的原因应该“打折扣”。 A 项，不完全是因为洗发水才有的，说明人们不完全相信某一现象的形成是由于某种 原因导致，符合归因折扣原则，排除； B 项，大多数争议与财产纠纷有关，说明离婚诉讼中的争议大部分涉及的是财产纠纷， 财产纠纷是争议的一种，未涉及因果关系，因此不符合两类归因原则，当选； C 项，创业失败总会使创业者背负债务，体现了某种特定原因，在许多情境下总是与某 种结果相伴。朋友认为他一定是创业失败了，体现了人们就会把特定结果归结于 那一原因，符合归因不变性原则，符合定义，排除； D 项，现场都出现过同一个男人，体现了某种特定原因，人们容易假定该男人就是犯 罪嫌疑人，体现了人们就会把特定",
