   "module": "panduan",
   "q": "由于人类建设活动的破坏和干扰，生物群体原来连续成片的生活环境被割裂，形成分散的岛状甚至碎片状的生境，生境廊道是指连接破碎化生境并适宜生物生活、移动或扩散的通道，便于实现物种基因、能量、物质的流动。根据上述定义，下列不属于生境廊道的是（ ）",
   "options": [
    "国家公园内，两棵参天古树跨过公路上方枝叶相连，金丝猴借助古树跨越公路。不同区域的金丝猴群可以保持接触",
    "为了野生象群在两个自然保护区之间迁移，管理者设计建成了迁移通道，避开村寨，并保证该区域范围内有丰富的水和食物资源",
    "为避免青藏铁路隔断藏羚羊迁徙路线，动物学家设计了桥梁下方隧道、上方及路基缓坡三种形式的野生动物通路",
    "某地将过去严重污染的河道改造为河滨公园，架设了多座拱桥，美化了环境，方便了交通，还吸引了大量鸟类来此栖息"
   ],
   "answer": 3,
   "explain": "】定义判断，选非题。关键词：连接破碎化生境并适宜生物生活移动或扩散的通道。 A 项，大树跨过公路，枝叶相连方便金丝猴保持接触，符合关键词连接破碎化生境并 适宜生物生活移动或扩散的通道，符合定义，排除； B 项，管理者为象群设计迁移的通道，符合关键词：连接破碎化生境并适宜生物生活移 动或扩散的通道，符合定义，排除； C 项，为避免铁路隔断藏羚羊的迁徙路线，动物学家设计了野生动物通道，符合关键词 连接破碎化生境并适宜生物生活移动或扩散的通道，符合定义，排除； D 项，将河道改为公园仅是美化环境，方便交通，没有提及是否为生物生活移动或扩 散的通道，吸引来的鸟类也仅仅是栖息而已，并不是生物生活移动或扩散的通道， 不符合关键词：连接破碎化生境并适宜生物生活移动或扩散的通道，不符合定义， 当选。 全国服务电话：400-6353-606 故正确答案为D。",
