   "module": "panduan",
   "q": "刑事科学技术是公安、司法机关依照刑事诉讼法的规定，应用现代科学技术的成果，收集、检验和鉴定与犯罪活动有关的物证，为侦查、起诉、审判工作提供线索和证据的专门技术。根据上述定义，下列没有体现刑事科学技术的是（ ）",
