   "explain": "】本题考查科技常识。 A 项，费曼，美国著名理论物理学家，1965 年，因在量子电动力学方面的成就而获得 诺贝尔物理学奖。“没有人真正了解量子力学”为其名言； B 项，卢瑟福，英国著名物理学家，被称为原子核物理学之父。学术界公认他为继迈克 尔·法拉第之后最伟大的实验物理学家。而“固执于光的旧有理论的人们，最好 是从它自身的原理出发，提出实验的说明”是英国著名物理学家托马斯·杨的名 言； C 项，麦克斯韦，出生于苏格兰爱丁堡，英国物理学家、数学家。经典电动力学的创始 人，统计物理学的奠基人之一。“电和磁的实验中最明显的现象是，处于彼此距 离相当远的物体之间的相互作用”为其名言； D 项，牛顿，英国著名的物理学家、数学家，被称为百科全书式的“全才”，著有《自 然哲学的数学原理》、《光学》。“万有引力、电的相互作用和磁的相互作用，可 以在很远的地方明显的表现出来，因此用肉眼就可以观察到”为其名言",
