   "id": "xc-2022-gk-fsheng-14",
   "module": "changshi",
   "q": "我国自古十分重视对人的品德的培养。下列有关“德”的表述与出处对应错误的是（ ）",
   "options": [
    "大德不逾闲，小德出入可也——《论语》",
    "富有之谓大业，日新之谓盛德——《周易》",
    "所求于己者多，故德行立——《管子》",
    "道生之，德畜之，物形之，势成之——《庄子》"
   ],
   "answer": 3,
   "explain": "】本题考查文学常识。 A 项，“大德不逾闲，小德出入可也。”出自儒家典籍《论语》。这句话的意思是：大 节上不能超越界限，小节上有些出入是可以的。选项对应正确； B 项，“富有之谓大业，日新之谓盛德”出自《周易·系辞上传》。这句话的意思是： 广泛创造物质财富和精神财富叫做弘大功业，持续永远的日日增新叫做盛美德行。 选项对应正确； C 项，“所求于己者多，故德行立”出自《管子·君臣》。这句话的意思是：严于律己, 高尚的品德就树立起来了。选项对应正确； D 项，“道生之，德畜之，物形之，势成之”出自老子的《道德经》第五十一章。此句 话的意思是：道生成万事万物，德养育万事万物。万事万物虽现出各种各样的形 态，环境使万事万物成长起来。选项对应错误。 故正确答案为D。",
   "year": 2022,
   "exam_type": "gk-fsheng",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
   "url": ""
