   "id": "xc-2022-gk-fsheng-15",
   "module": "changshi",
   "q": "我国很多成语都与植物有关，下列有关说法错误的是（ ）",
   "options": [
    "“投桃报李”中的“桃”和“李”属于同一科植物",
    "“藕断丝连”中藕丝的作用是为植物输送水和养分",
    "“望梅止渴”和“折梅寄远”中的“梅”分别是果梅和花梅",
    "“胸有成竹”中“竹”的年龄可以根据竹节的数量判断"
   ],
   "answer": 3,
   "explain": "】本题考查科技常识。D 项，“竹”的年龄可以根据以下判断，①从竹质判断：年份 短的幼竹，质地太嫩，而年份太久的笛子，经长期自然风化，竹质已经枯僵脆化；② 从竹节的颜色判断：全身带白霜的是当年的新生竹，竹节带有霜的竹龄为一年。竹龄 越大颜色越深，也随之开始泛黄。超过15 年的竹子就开始发灰了，逐渐干枯死亡。③ 从竹叶的颜色判断：从竹叶的颜色上也可以识别竹子的老嫩。嫩竹的竹叶翠绿欲滴， 而老竹的竹叶就显得略带枯黄了。并不能从竹节的数量判断竹子的年龄，故D 项错误。 故正确答案为D。",
