   "module": "yanyu",
   "q": "实施传统胸外按压心肺复苏，常会发生肋骨或胸骨骨折，导致肺、胸膜及心脏损伤，影响心肺复苏的成功率，急救专家由此探索出“胸路不通走腹路”的新路径，腹部提压心肺复苏技术及提压心肺复苏技术______。与传统心肺复苏技术相比，该技术______，利用腹部提压心肺复苏仪达到起腹心动、起腹呼吸的目的。依次填入划横线部分最恰当的一项是（ ）",
