   "explain": "】逻辑填空题。第一空，根据空前“建筑工程投入巨大”可知，该空应体现出建成 后再拆改会浪费财物的含义。 A 项，“徒劳无功”指白费力气，没有功效，侧重劳而无功，文段中拆改投入巨大的 建筑工程不仅仅只是没有功效，还会产生更严重的后果，不符合文意，排除； B 项，“劳民伤财”指既让百姓劳苦，又耗费了钱财，侧重滥用人力物力，符合文 意，保留； C 项，“得不偿失”指得到的抵不过失掉的，符合文意，保留； D 项，“血本无归”指本钱赔光了，一点也没收回，符合文意，保留。 第二空，根据“从方案设计一开始就强化监管审核……符合城市设计要求”可知，该 空应体现提前做好计划，避免导致不好结果的含义。 B 项，“木已成舟”比喻事情已成为不可改变的定局，符合文意，当选； C 项，“尾大不掉”比喻部下势力太大，不易指挥调度，或因事物轻重关系倒置，形 成难以驾驭的局面，不符合文意，排除； D 项，“闭门造车”比喻只凭",
