   "answer": 3,
   "explain": "】逻辑填空题。第一空，根据提示信息“解剖无疑会破坏珍贵的样本”可知，会造 成很大的损害。 A 项，“难以估量”指很难估计，很难猜测，保留； B 项，“触目惊心”指看到某种严重的情况引起内心的震动，不符合文意，排除； C 项，“毋庸置疑”指事实明显或理由充分，没有怀疑的余地，不符合文意，排除； D 项，“不言而喻”表示不用说就能明白，保留。 第二空，搭配“相关技术的应用”，空前提示信息为“已开始应用于多个领域”可 知，能找到相关的参照。 A 项，“拓展”指开拓展开，不符合文意，排除； D 项，“借鉴”比喻别人的、可供自己对照学习的经验或吸取的教训，符合文意，当 选。 故正确答案为D。",
