   "id": "xc-2022-gk-fsheng-29",
   "module": "yanyu",
   "q": "人体肠道内生物的多样性令人惊讶，除细菌外，还______着数十万种被称为噬菌体的病毒，这些噬菌体可以感染细菌。众所周知，肠道微生物组不平衡会引发各种疾病，如炎症性肠病、过敏和肥胖，但我们对肠道细菌及噬菌体在人类健康和疾病方面起何种作用却______。依次填入画横线部分最恰当的一项是（ ）",
