   "module": "yanyu",
   "q": "稳就业之“稳”，既要着眼于______存量，让大家把“饭碗”端稳，更要着眼于扩大增量，拓宽就业空间。一方面需要不断优化营商环境，让新增市场主体成为解决就业的______；另一方面还要充分利用新技术衍生的新业态，引导人们转变观念，实现更宽更广的就业。依次填入画横线部分最恰当的一项是（ ）",
