   "q": "病毒变异每时每刻都在发生，随机性极大，突变率高，变异速度快，这意味着它们更有机会形成适应环境的______。然而，并非每种变异都能让病毒存活并发展下去。同一时期，病毒的变异株可能有很多种，但“______”，只有那些能更有效______免疫系统侦测且传播能力强的毒株才能最终成为优势株。依次填入画横线部分最恰当的一项是（ ）",
