   "explain": "】等差等比数列相关。假设去年1 月份桃汁、橙汁的销量分别为x、y，则去年2 月 ×项数，因此1 季度桃汁和橙汁的销量分别为3(x + 5000)、3(y + 2000)，根据题意 可得：3(x + 5000) −3(y + 2000) = 45000，化简可得3x −3y = −54000。同理可得 去年12 月份桃汁的销量为x + 55000，橙汁的销量为y + 22000，根据等差数列求和 2 × 项数，则全年的销量分别为 首项+末项 2 × 12 = 12y + 132000，则去年全年桃汁比橙汁多：(12x + 330000) − 公式： y+(y+22000) (12y + 132000) = 12x −12y + 198000，因3x −3y = −54000，所以12x −12y + 198000 = 4(3x −3y) + 198000 = −54000 × 4 + 198",
