   "module": "shuliang",
   "q": "救灾部门紧急运送两批大米分给受灾群众。已知甲村人数是丙村的2 倍，如果两批大米都给甲村，每人正好能分24 斤；如果第一批大米分给乙村，每人正好能分12 斤，第二批大米分给甲、乙、丙三个村，每人正好能分4 斤。为尽量保障受灾群众的基本需求，现决定另运送一批面粉分给甲村，并将两批大米都分给乙、丙两村。问乙、丙两村平均每人分到的大米重量在以下哪个范围内（ ）",
