   "module": "shuliang",
   "q": "为降低碳排放，企业对生产设备进行改造，改造后日产量下降了10%，但生产每件产品的能耗成本下降了50%，其他成本和出厂价不变的情况下每天的利润提高了10%。已知单件利润=出厂价−能耗成本−其他成本，且改造前产品的出厂价是单件利润的3倍，则改造前能耗成本为其他成本的（ ）1",
