   "id": "xc-2022-gk-fsheng-92",
   "module": "panduan",
   "q": "基因污染指原生物种基因库非预期或不受控制的基因流动，即外源基因通过转基因作物、外来入侵物种、家养动物等扩散到其他栽培作物或自然野生物种并成为后者基因的一部分。根据上述定义，下列没有体现出基因污染的是（ ）",
   "options": [
    "某农场生产的大豆发现了转基因成分Bt 基因，这些成分是附近地区种植的基因工程Bt 大豆通过交叉授粉传播过来的",
    "黑足猫是一种体型娇小但捕猎能力超强的野生猫，跑到野外的家猫和黑足猫交配后，生出血统不纯正的黑足猫，真正的黑足猫几近灭绝",
    "转基因SL 玉米获批做动物饲料，SL 玉米只占某国玉米总产量的1%，但一年后该国22%的玉米样本被认定含有SL 玉米基因",
    "某国开发出耐除草剂的转基因油菜，油菜出油率提高，但这种油菜种子能在土壤中休眠数年，因此成为其他作物中的“杂草”"
   ],
   "answer": 3,
   "explain": "】定义判断，选非题。关键词：原生物种基因库；外源基因；扩散到其他栽培作物 或自然野生物种；成为后者基因的一部分。 A 项，转基因成分Bt 基因通过交叉授粉的方式传播到农产生产的大豆上，并成为了大 豆基因的一部分，符合定义，排除； B 项，家猫和黑足猫交配后生出的血统不纯正的黑足猫，属于家养动物扩散到自然野 生物种中，并成为血统不纯正的黑足猫基因的一部分，符合定义，排除； C 项，一年后22%的玉米样本被认定含有SL 玉米基因，属于外源基因通过转基因作物 扩散到其他栽培作物并成为后者基因的一部分，符合定义，排除； D 项，油菜种子在土壤中休眠数年，并没有体现基因流动，不符合定义，当选。 故正确答案为D。",
   "year": 2022,
   "exam_type": "gk-fsheng",
   "exam_volume": "行测",
