   "id": "xc-2022-gk-fsheng-93",
   "module": "panduan",
   "q": "地球物理勘探是通过研究和观测各种地球物理场的变化来探测地层岩性、地质构造等地质条件的过程。由于组成地壳的不同岩层介质往往在密度、弹性、导电性等方面存全国服务电话：400-6353-606在差异，这些差异将引起相应的地球物理场的局部变化，通过测量这些物理场的分布和变化特征，结合已知地质资料进行分析研究，就可以达到推断地质性状的目的。根据上述定义，下列不属于地球物理勘探的是（ ）",
   "options": [
    "根据岩石和矿石导电性、电磁感应特性等来记录地层界面的深度和形态",
    "利用人工激发的地震波在弹性不同地层内的传播规律，了解水文地质的分布情况",
    "采集岩石样品，分析岩石内的微量元素，通过发现与矿化有关的原生异常来寻找矿床",
    "通过观测不同岩石引起的重力差异，判断地下地层的岩性及状态，确定沉积盆地范围"
   ],
   "answer": 2,
   "explain": "】定义判断，选非题。关键词：不同岩层介质存在差异；通过测量这些物理场的分 布和变化特征；结合已知地质资料进行分析研究。 A 项，岩石和矿石导电性、电磁感应特性符合关键词不同岩层介质往往在密度、弹性、 全国服务电话：400-6353-606 导电性等方面存在差异，根据这些特性记录地层界面的深度和形态符合关键词通 过这些物理场的分布和变化特征，结合已知地质资料进行分析研究，符合定义， 排除； B 项，人工激发的地震波在弹性不同地层内的传播符合关键词不同岩层存在差异，利 用此规律了解水文地质的分布情况符合关键词通过测量这些物理场的分布和变化 特征，结合已知地质资料进行分析研究，符合定义，排除； C 项，该项仅通过岩石样品分析岩石内的微量元素不存在岩层介质间的差异，也未通 过这些特征进行分析研究，不符合定义，当选； D 项，不同岩石引起的重力差异符合关键词不同岩层介质存在差异，判断地",
