   "id": "xc-2022-gk-fsheng-111",
   "module": "panduan",
   "q": "地理老师在五个柜子里放入了五种矿物，每个柜子只放一种矿物：赤铁矿、黑云母、绿泥石、黄铜矿、方铅矿。已知：（1）如果一号柜放赤铁矿，那么二号柜不放黑云母；（2）或者三号柜放赤铁矿，或者一号柜放赤铁矿；（3）如果二号柜不放黑云母，那么四号柜不放绿泥石；（4）若五号柜放方铅矿，那么四号柜放绿泥石；以下哪项如果为真，可以得出“三号柜放赤铁矿”的结论（ ）",
   "options": [
    "二号柜不放黑云母",
    "四号柜不放绿泥石",
    "五号柜放的是方铅矿",
    "一号柜不放黄铜矿"
   ],
   "answer": 2,
   "explain": "】翻译推理。翻译题干：（1）一号赤铁矿→-二号黑云母；（2）三号赤铁矿或一号 赤铁矿；（3）-二号黑云母→-四号绿泥石；（4）五号方铅矿→四号绿泥石。将提问条 件带入翻译逐一反推。 要得到三号柜放赤铁矿，由条件（2）否一推一可知一号柜一定不放赤铁矿；要得到一 号柜不放赤铁矿，由条件（1）否后必否前可知二号柜一定放黑云母；要得到二号柜一 定放黑云母，由条件（3）否后必否前可知，四号柜一定放绿泥石；要得到四号柜放绿 泥石，由条件（4）肯前必肯后可知，五号柜一定放方铅矿。所以要得到三号柜放赤铁 矿所需要的条件是第五个柜子放方铅矿。 故正确答案为C。",
