   "explain": "】本题考查科技常识。 A 项，我国的火箭不只有长征系列火箭。1975 年7 月26 日，由风暴一号发射成功的长 空一号卫星，是中国质量最重的卫星。风暴系列运载火箭十分短命，仅有风暴一 号一代产品，但它对于我国航天事业的贡献，也是不可估量的，故A 项错误； B 项，我国第一颗地球同步轨道卫星是于1984 年4 月8 日在西昌发射的，而不是文 昌，故B 项错误； C 项，2021 年6 月17 日9 时22 分，神舟十二号载人飞船从酒泉卫星发射中心发射升 空，准确进入预定轨道，并成功将三名宇航员送入太空。神舟十二号载人飞船在 进入轨道后成功完成了轨道状态的设定。2021 年6 月17 日北京时间15 时54 分， 采用自主快速交会对接方式，成功停靠在天和核心舱前方港口，与此前停靠的天 舟二号货运飞船形成三舱(船)组合，整个交会对接过程持续约6.5 小时，这是天 和核心舱发射进入轨道后首次与载人",
