   "module": "yanyu",
   "q": "解剖是认识某种动物体内形态特征的重要方式，但对于罕见或稀有物种而言，解剖无疑会破坏珍贵的样本，其损失______。近年来，无损检测已开始应用于文物鉴定等多种领域，______相关技术的应用经验，研发出一套专门针对珍稀动物样本无损检测的方法，必将大有可为。依次填入画横线处最恰当的一项是（ ）",
