   "id": "xc-2022-gk-xzf-59",
   "module": "yanyu",
   "q": "科学家发现，人类基因组里除了与编码蛋白质有关的特异性DNA 序列之外，还有相当一部分重复DNA 序列。基因测序结果表明，在同一人类个体的基因组中，这些序列有的重复几次，有的重复成千上万次；其中既有长达20 万个碱基对的片段重复，也包括短的简单序列；重复的基本单位有时只有一个碱基，有时包含几个碱基。它们加起来甚至超过了人类基因组的一半。在过去，研究者认为这些重复序列不过是DNA复制过程中的副产物，然而随着认识的深入，他们开始意识到那些曾被认为是毫无用处的重复DNA 序列，对基因表达和决定生物性状至关重要。这段文字接下来最可能介绍（ ）",
   "options": [
    "不同物种的重复，DNA 序列有何差异全国服务电话：400-6353-606",
    "重复DNA 序列如何影响生物基因表达",
    "DNA 序列在重复的过程中遵循哪些规矩",
    "特异性DNA 序列在基因表达中所占的比例"
   ],
   "answer": 1,
   "explain": "】下文推断题。延续主干话题，文段开篇说明人类基因组里除了特异性DNA 序列 外，还有相当一部分重复DNA 序列，随后指出DNA 的形态和占比，最后强调DNA 对 基因和生物性状的重要性，故文段尾句话题为“重复DNA 序列对基因表达和决定生 物性状至关重要”，对应B 项。 A 项和C 项以及D 项，均没有提到“重复DNA 序列”，不能延续话题，排除。 故正确答案为B。",
