   "module": "panduan",
   "q": "归因不变性原则是指人们会寻找某一特定结果与特定原因之间的不变联系，如果某种特定原因在许多情境下总是与某种结果相伴，人们就会把特定结果归结于那一原因。归因折扣原则是指人们不完全相信某一现象的形成确是由于某种原因导致，即某一特定原因在产生特定结果中的作用，如果存在其他似是而非的原因应该“打折扣”。根据上述定义，两类归因原则均没有体现的是（ ）",
